{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall implement a multi-layer safety architecture with passive, active, and functional safety mechanisms to ensure collision protection and fail-safe operations.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-01", "RES-02"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall execute a Minimal Risk Maneuver within 5 seconds upon detecting critical system failures to safely pull over to a low-risk zone.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-02", "EFF-03", "RES-03"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-03",
      "text": "The system shall continuously monitor Operational Design Domain compliance and issue a human takeover request when boundaries are approached.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["SAF-03", "EFF-04", "RES-04"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-04",
      "text": "The system shall minimize jerk to less than 0.5 m/s³ during normal operation while ensuring safety during emergencies.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-04", "EFF-02", "RES-06"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-05",
      "text": "The system shall satisfy curvature constraints to prevent rollover during maneuvers at all speeds.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-06",
      "text": "The system shall utilize iterative quadratic programming to handle non-convex obstacle constraints reliably within a response time of 100 milliseconds.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["SAF-06", "EFF-06"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-07",
      "text": "The system shall establish emergency protocols that minimize energy usage during critical failures while ensuring safety.",
      "quality_axes": ["Efficiency", "Safety", "Sustainability"],
      "derived_from": ["GRN-07"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-08",
      "text": "The system shall implement end-to-end data encryption for all user data transmitted to protect privacy and ensure data integrity.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall enforce role-based access control to restrict user permissions based on their role within the system.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The system shall log all access and modifications to critical data for auditability purposes.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The system shall implement a mechanism for secure remote software updates to protect against malware and ensure integrity.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-06"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The system shall conduct regular security audits at least bi-annually to identify and mitigate potential vulnerabilities.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-05"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The system shall optimize path planning to achieve a minimum 30% reduction in average travel time compared to baseline scenarios.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The system shall achieve at least 95% success rate in optimal speed profile generation during path planning.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-05"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The system shall provide timely HMI warnings to request human takeover whenever ODD compliance is at risk.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-05"],
      "kaos_level": "tactical",
      "parent": null
    }
  ],
  "conflict_resolutions": [
    {
